import { graphql } from '$flamme'

export const ToggleFavorite = graphql`mutation ToggleFavorite($id: Int!) {
	toggleFavorite(id: $id) {
		species {
			id
			favorite
			...FavoriteSpecies_toggle
		}
	}
}
`

query Favorites @loading {
	favorites @list(name: "FavoriteSpecies") {
		id
		...FavoritePreview
	}
}

query Info($id: Int! = 1) @loading {
	species(id: $id, delay: 500) {
		id
		pokedexNumber
		name
		flavor_text
		favorite
		...SpriteInfo
		evolution_chain {
			id
			...SpeciesPreview
		}
		moves(first: 1) @paginate(mode: SinglePage, name: "Species_Moves") {
			edges @loading(count: 1) {
				node {
					...MoveDisplay @mask_enable
				}
			}
			pageInfo {
				hasNextPage
				hasPreviousPage
			}
		}
	}
}

