fragment FavoritePreview on Species @loading {
	id
	pokedexNumber
	name
	sprites {
		front
	}
}

fragment MoveDisplay on SpeciesMove @loading {
	learned_at
	method
	move {
		name
		accuracy
		power
		pp
		type
	}
}

fragment SpeciesPreview on Species @loading {
	name
	id
	pokedexNumber
	...SpriteInfo
}

fragment SpriteInfo on Species @loading {
	name
	sprites {
		front
	}
}

mutation ToggleFavorite($id: Int!) {
	toggleFavorite(id: $id) {
		species {
			id
			favorite
			...FavoriteSpecies_toggle
		}
	}
}

